head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsStrtDt = ""; // 조회조건 결산일자 시작
scwin.vAcntclsEndDt = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 조회조건 결산일자 종료

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    // 결산일자 조회
    // 결산일자 검색(FROM-TO)로 변경되어 아래 로직 삭제
    // frame.Provider("../frame_head").fn_SrchAcntclsDt();

    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_MajShrhd_OnLoadError
 * @description dts_MajShrhd 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MajShrhd_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MajShrhd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00203.dts_MajShrhd_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MajShrhd_OnLoadCompleted
 * @description dts_MajShrhd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MajShrhd_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_MajShrhd.errorMsg) {
            alert(dts_MajShrhd.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00203.dts_MajShrhd_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 주요주주 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_MajShrhd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_MajShrhd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_MajShrhd.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    scwin.vAcntclsStrtDt = $c.frame.path("../frame_head").fn_GetAcntclsStrtDt();

    scwin.vAcntclsEndDt = $c.frame.path("../frame_head").fn_GetAcntclsEndDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsStrtDt === "" || scwin.vAcntclsEndDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDownload = function() {
    if (dts_MajShrhd.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_MajShrhd, {fileName: "주요주주", type: "1"});
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    await scwin.init();
};
